109: static COLD void get_num_threads(Dav1dContext *const c, const Dav1dSettings *const s,
110:                                  unsigned *n_tc, unsigned *n_fc)
111: {
112:     /* ceil(sqrt(n)) */
113:     static const uint8_t fc_lut[49] = {
114:         1,                                     /*     1 */
115:         2, 2, 2,                               /*  2- 4 */
116:         3, 3, 3, 3, 3,                         /*  5- 9 */
117:         4, 4, 4, 4, 4, 4, 4,                   /* 10-16 */
118:         5, 5, 5, 5, 5, 5, 5, 5, 5,             /* 17-25 */
119:         6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6,       /* 26-36 */
120:         7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, /* 37-49 */
121:     };
122:     *n_tc = s->n_threads ? s->n_threads :
123:         iclip(dav1d_num_logical_processors(c), 1, DAV1D_MAX_THREADS);
124:     *n_fc = s->max_frame_delay ? umin(s->max_frame_delay, *n_tc) :
125:             *n_tc < 50 ? fc_lut[*n_tc - 1] : 8; // min(8, ceil(sqrt(n)))
126: }
