128: COLD int dav1d_get_frame_delay(const Dav1dSettings *const s) {
129:     unsigned n_tc, n_fc;
130:     validate_input_or_ret(s != NULL, DAV1D_ERR(EINVAL));
131:     validate_input_or_ret(s->n_threads >= 0 &&
132:                           s->n_threads <= DAV1D_MAX_THREADS, DAV1D_ERR(EINVAL));
133:     validate_input_or_ret(s->max_frame_delay >= 0 &&
134:                           s->max_frame_delay <= DAV1D_MAX_FRAME_DELAY, DAV1D_ERR(EINVAL));
135: 
136:     get_num_threads(NULL, s, &n_tc, &n_fc);
137:     return n_fc;
138: }
