140: COLD int dav1d_open(Dav1dContext **const c_out, const Dav1dSettings *const s) {
141:     static pthread_once_t initted = PTHREAD_ONCE_INIT;
142:     pthread_once(&initted, init_internal);
143: 
144:     validate_input_or_ret(c_out != NULL, DAV1D_ERR(EINVAL));
145:     validate_input_or_ret(s != NULL, DAV1D_ERR(EINVAL));
146:     validate_input_or_ret(s->n_threads >= 0 &&
147:                           s->n_threads <= DAV1D_MAX_THREADS, DAV1D_ERR(EINVAL));
148:     validate_input_or_ret(s->max_frame_delay >= 0 &&
149:                           s->max_frame_delay <= DAV1D_MAX_FRAME_DELAY, DAV1D_ERR(EINVAL));
150:     validate_input_or_ret(s->allocator.alloc_picture_callback != NULL,
151:                           DAV1D_ERR(EINVAL));
152:     validate_input_or_ret(s->allocator.release_picture_callback != NULL,
153:                           DAV1D_ERR(EINVAL));
154:     validate_input_or_ret(s->operating_point >= 0 &&
155:                           s->operating_point <= 31, DAV1D_ERR(EINVAL));
156:     validate_input_or_ret(s->decode_frame_type >= DAV1D_DECODEFRAMETYPE_ALL &&
157:                           s->decode_frame_type <= DAV1D_DECODEFRAMETYPE_KEY, DAV1D_ERR(EINVAL));
158: 
159:     pthread_attr_t thread_attr;
160:     if (pthread_attr_init(&thread_attr)) return DAV1D_ERR(ENOMEM);
161:     size_t stack_size = 1024 * 1024 + get_stack_size_internal(&thread_attr);
162: 
163:     pthread_attr_setstacksize(&thread_attr, stack_size);
164: 
165:     Dav1dContext *const c = *c_out = dav1d_alloc_aligned(ALLOC_COMMON_CTX, sizeof(*c), 64);
166:     if (!c) goto error;
167:     memset(c, 0, sizeof(*c));
168: 
169:     c->allocator = s->allocator;
170:     c->logger = s->logger;
171:     c->apply_grain = s->apply_grain;
172:     c->operating_point = s->operating_point;
173:     c->all_layers = s->all_layers;
174:     c->frame_size_limit = s->frame_size_limit;
175:     c->strict_std_compliance = s->strict_std_compliance;
176:     c->output_invisible_frames = s->output_invisible_frames;
177:     c->inloop_filters = s->inloop_filters;
178:     c->decode_frame_type = s->decode_frame_type;
179: 
180:     dav1d_data_props_set_defaults(&c->cached_error_props);
181: 
182:     if (dav1d_mem_pool_init(ALLOC_OBU_HDR, &c->seq_hdr_pool) ||
183:         dav1d_mem_pool_init(ALLOC_OBU_HDR, &c->frame_hdr_pool) ||
184:         dav1d_mem_pool_init(ALLOC_SEGMAP, &c->segmap_pool) ||
185:         dav1d_mem_pool_init(ALLOC_REFMVS, &c->refmvs_pool) ||
186:         dav1d_mem_pool_init(ALLOC_PIC_CTX, &c->pic_ctx_pool) ||
187:         dav1d_mem_pool_init(ALLOC_CDF, &c->cdf_pool))
188:     {
189:         goto error;
190:     }
191: 
192:     if (c->allocator.alloc_picture_callback   == dav1d_default_picture_alloc &&
193:         c->allocator.release_picture_callback == dav1d_default_picture_release)
194:     {
195:         if (c->allocator.cookie) goto error;
196:         if (dav1d_mem_pool_init(ALLOC_PIC, &c->picture_pool)) goto error;
197:         c->allocator.cookie = c->picture_pool;
198:     } else if (c->allocator.alloc_picture_callback   == dav1d_default_picture_alloc ||
199:                c->allocator.release_picture_callback == dav1d_default_picture_release)
200:     {
201:         goto error;
202:     }
203: 
204:     /* On 32-bit systems extremely large frame sizes can cause overflows in
205:      * dav1d_decode_frame() malloc size calculations. Prevent that from occuring
206:      * by enforcing a maximum frame size limit, chosen to roughly correspond to
207:      * the largest size possible to decode without exhausting virtual memory. */
208:     if (sizeof(size_t) < 8 && s->frame_size_limit - 1 >= 8192 * 8192) {
209:         c->frame_size_limit = 8192 * 8192;
210:         if (s->frame_size_limit)
211:             dav1d_log(c, "Frame size limit reduced from %u to %u.\n",
212:                       s->frame_size_limit, c->frame_size_limit);
213:     }
214: 
215:     c->flush = &c->flush_mem;
216:     atomic_init(c->flush, 0);
217: 
218:     get_num_threads(c, s, &c->n_tc, &c->n_fc);
219: 
220:     c->fc = dav1d_alloc_aligned(ALLOC_THREAD_CTX, sizeof(*c->fc) * c->n_fc, 32);
221:     if (!c->fc) goto error;
222:     memset(c->fc, 0, sizeof(*c->fc) * c->n_fc);
223: 
224:     c->tc = dav1d_alloc_aligned(ALLOC_THREAD_CTX, sizeof(*c->tc) * c->n_tc, 64);
225:     if (!c->tc) goto error;
226:     memset(c->tc, 0, sizeof(*c->tc) * c->n_tc);
227:     if (c->n_tc > 1) {
228:         if (pthread_mutex_init(&c->task_thread.lock, NULL)) goto error;
229:         if (pthread_cond_init(&c->task_thread.cond, NULL)) {
230:             pthread_mutex_destroy(&c->task_thread.lock);
231:             goto error;
232:         }
233:         if (pthread_cond_init(&c->task_thread.delayed_fg.cond, NULL)) {
234:             pthread_cond_destroy(&c->task_thread.cond);
235:             pthread_mutex_destroy(&c->task_thread.lock);
236:             goto error;
237:         }
238:         c->task_thread.cur = c->n_fc;
239:         atomic_init(&c->task_thread.reset_task_cur, UINT_MAX);
240:         atomic_init(&c->task_thread.cond_signaled, 0);
241:         c->task_thread.inited = 1;
242:     }
243: 
244:     if (c->n_fc > 1) {
245:         const size_t out_delayed_sz = sizeof(*c->frame_thread.out_delayed) * c->n_fc;
246:         c->frame_thread.out_delayed =
247:             dav1d_malloc(ALLOC_THREAD_CTX, out_delayed_sz);
248:         if (!c->frame_thread.out_delayed) goto error;
249:         memset(c->frame_thread.out_delayed, 0, out_delayed_sz);
250:     }
251:     for (unsigned n = 0; n < c->n_fc; n++) {
252:         Dav1dFrameContext *const f = &c->fc[n];
253:         if (c->n_tc > 1) {
254:             if (pthread_mutex_init(&f->task_thread.lock, NULL)) goto error;
255:             if (pthread_cond_init(&f->task_thread.cond, NULL)) {
256:                 pthread_mutex_destroy(&f->task_thread.lock);
257:                 goto error;
258:             }
259:             if (pthread_mutex_init(&f->task_thread.pending_tasks.lock, NULL)) {
260:                 pthread_cond_destroy(&f->task_thread.cond);
261:                 pthread_mutex_destroy(&f->task_thread.lock);
262:                 goto error;
263:             }
264:         }
265:         f->c = c;
266:         f->task_thread.ttd = &c->task_thread;
267:         f->lf.last_sharpness = -1;
268:     }
269: 
270:     for (unsigned m = 0; m < c->n_tc; m++) {
271:         Dav1dTaskContext *const t = &c->tc[m];
272:         t->f = &c->fc[0];
273:         t->task_thread.ttd = &c->task_thread;
274:         t->c = c;
275:         memset(t->cf_16bpc, 0, sizeof(t->cf_16bpc));
276:         if (c->n_tc > 1) {
277:             if (pthread_mutex_init(&t->task_thread.td.lock, NULL)) goto error;
278:             if (pthread_cond_init(&t->task_thread.td.cond, NULL)) {
279:                 pthread_mutex_destroy(&t->task_thread.td.lock);
280:                 goto error;
281:             }
282:             if (pthread_create(&t->task_thread.td.thread, &thread_attr, dav1d_worker_task, t)) {
283:                 pthread_cond_destroy(&t->task_thread.td.cond);
284:                 pthread_mutex_destroy(&t->task_thread.td.lock);
285:                 goto error;
286:             }
287:             t->task_thread.td.inited = 1;
288:         }
289:     }
290:     dav1d_pal_dsp_init(&c->pal_dsp);
291:     dav1d_refmvs_dsp_init(&c->refmvs_dsp);
292: 
293:     pthread_attr_destroy(&thread_attr);
294: 
295:     return 0;
296: 
297: error:
298:     if (c) close_internal(c_out, 0);
299:     pthread_attr_destroy(&thread_attr);
300:     return DAV1D_ERR(ENOMEM);
301: }
