303: static int has_grain(const Dav1dPicture *const pic)
304: {
305:     const Dav1dFilmGrainData *fgdata = &pic->frame_hdr->film_grain.data;
306:     return fgdata->num_y_points || fgdata->num_uv_points[0] ||
307:            fgdata->num_uv_points[1] || (fgdata->clip_to_restricted_range &&
308:                                         fgdata->chroma_scaling_from_luma);
309: }
