311: static int output_image(Dav1dContext *const c, Dav1dPicture *const out)
312: {
313:     int res = 0;
314: 
315:     Dav1dThreadPicture *const in = (c->all_layers || !c->max_spatial_id)
316:                                    ? &c->out : &c->cache;
317:     if (!c->apply_grain || !has_grain(&in->p)) {
318:         dav1d_picture_move_ref(out, &in->p);
319:         dav1d_thread_picture_unref(in);
320:         goto end;
321:     }
322: 
323:     res = dav1d_apply_grain(c, out, &in->p);
324:     dav1d_thread_picture_unref(in);
325: end:
326:     if (!c->all_layers && c->max_spatial_id && c->out.p.data[0]) {
327:         dav1d_thread_picture_move_ref(in, &c->out);
328:     }
329:     return res;
330: }
331: 
332: static int output_picture_ready(Dav1dContext *const c, const int drain) {
333:     if (c->cached_error) return 1;
334:     if (!c->all_layers && c->max_spatial_id) {
335:         if (c->out.p.data[0] && c->cache.p.data[0]) {
336:             if (c->max_spatial_id == c->cache.p.frame_hdr->spatial_id ||
337:                 c->out.flags & PICTURE_FLAG_NEW_TEMPORAL_UNIT)
338:                 return 1;
339:             dav1d_thread_picture_unref(&c->cache);
340:             dav1d_thread_picture_move_ref(&c->cache, &c->out);
341:             return 0;
342:         } else if (c->cache.p.data[0] && drain) {
343:             return 1;
344:         } else if (c->out.p.data[0]) {
345:             dav1d_thread_picture_move_ref(&c->cache, &c->out);
346:             return 0;
347:         }
348:     }
349: 
350:     return !!c->out.p.data[0];
351: }
352: 
353: static int drain_picture(Dav1dContext *const c, Dav1dPicture *const out) {
354:     unsigned drain_count = 0;
355:     int drained = 0;
356:     do {
357:         const unsigned next = c->frame_thread.next;
358:         Dav1dFrameContext *const f = &c->fc[next];
359:         pthread_mutex_lock(&c->task_thread.lock);
360:         while (f->n_tile_data > 0)
361:             pthread_cond_wait(&f->task_thread.cond,
362:                               &f->task_thread.ttd->lock);
363:         Dav1dThreadPicture *const out_delayed =
364:             &c->frame_thread.out_delayed[next];
365:         if (out_delayed->p.data[0] || atomic_load(&f->task_thread.error)) {
366:             unsigned first = atomic_load(&c->task_thread.first);
367:             if (first + 1U < c->n_fc)
368:                 atomic_fetch_add(&c->task_thread.first, 1U);
369:             else
370:                 atomic_store(&c->task_thread.first, 0);
371:             atomic_compare_exchange_strong(&c->task_thread.reset_task_cur,
372:                                            &first, UINT_MAX);
373:             if (c->task_thread.cur && c->task_thread.cur < c->n_fc)
374:                 c->task_thread.cur--;
375:             drained = 1;
376:         } else if (drained) {
377:             pthread_mutex_unlock(&c->task_thread.lock);
378:             break;
379:         }
380:         if (++c->frame_thread.next == c->n_fc)
381:             c->frame_thread.next = 0;
382:         pthread_mutex_unlock(&c->task_thread.lock);
383:         const int error = f->task_thread.retval;
384:         if (error) {
385:             f->task_thread.retval = 0;
386:             dav1d_data_props_copy(&c->cached_error_props, &out_delayed->p.m);
387:             dav1d_thread_picture_unref(out_delayed);
388:             return error;
389:         }
390:         if (out_delayed->p.data[0]) {
391:             const unsigned progress =
392:                 atomic_load_explicit(&out_delayed->progress[1],
393:                                      memory_order_relaxed);
394:             if ((out_delayed->visible || c->output_invisible_frames) &&
395:                 progress != FRAME_ERROR)
396:             {
397:                 dav1d_thread_picture_ref(&c->out, out_delayed);
398:                 c->event_flags |= dav1d_picture_get_event_flags(out_delayed);
399:             }
400:             dav1d_thread_picture_unref(out_delayed);
401:             if (output_picture_ready(c, 0))
402:                 return output_image(c, out);
403:         }
404:     } while (++drain_count < c->n_fc);
405: 
406:     if (output_picture_ready(c, 1))
407:         return output_image(c, out);
408: 
409:     return DAV1D_ERR(EAGAIN);
410: }
411: 
412: static int gen_picture(Dav1dContext *const c)
413: {
414:     Dav1dData *const in = &c->in;
415: 
416:     if (output_picture_ready(c, 0))
417:         return 0;
418: 
419:     while (in->sz > 0) {
420:         const ptrdiff_t res = dav1d_parse_obus(c, in);
421:         if (res < 0) {
422:             dav1d_data_unref_internal(in);
423:         } else {
424:             assert((size_t)res <= in->sz);
425:             in->sz -= res;
426:             in->data += res;
427:             if (!in->sz) dav1d_data_unref_internal(in);
428:         }
429:         if (output_picture_ready(c, 0))
430:             break;
431:         if (res < 0)
432:             return (int)res;
433:     }
434: 
435:     return 0;
436: }
