438: int dav1d_send_data(Dav1dContext *const c, Dav1dData *const in)
439: {
440:     validate_input_or_ret(c != NULL, DAV1D_ERR(EINVAL));
441:     validate_input_or_ret(in != NULL, DAV1D_ERR(EINVAL));
442: 
443:     if (in->data) {
444:         validate_input_or_ret(in->sz > 0 && in->sz <= SIZE_MAX / 2, DAV1D_ERR(EINVAL));
445:         c->drain = 0;
446:     }
447:     if (c->in.data)
448:         return DAV1D_ERR(EAGAIN);
449:     dav1d_data_ref(&c->in, in);
450: 
451:     int res = gen_picture(c);
452:     if (!res)
453:         dav1d_data_unref_internal(in);
454: 
455:     return res;
456: }
