458: int dav1d_get_picture(Dav1dContext *const c, Dav1dPicture *const out)
459: {
460:     validate_input_or_ret(c != NULL, DAV1D_ERR(EINVAL));
461:     validate_input_or_ret(out != NULL, DAV1D_ERR(EINVAL));
462: 
463:     const int drain = c->drain;
464:     c->drain = 1;
465: 
466:     int res = gen_picture(c);
467:     if (res < 0)
468:         return res;
469: 
470:     if (c->cached_error) {
471:         const int res = c->cached_error;
472:         c->cached_error = 0;
473:         return res;
474:     }
475: 
476:     if (output_picture_ready(c, c->n_fc == 1))
477:         return output_image(c, out);
478: 
479:     if (c->n_fc > 1 && drain)
480:         return drain_picture(c, out);
481: 
482:     return DAV1D_ERR(EAGAIN);
483: }
