485: int dav1d_apply_grain(Dav1dContext *const c, Dav1dPicture *const out,
486:                       const Dav1dPicture *const in)
487: {
488:     validate_input_or_ret(c != NULL, DAV1D_ERR(EINVAL));
489:     validate_input_or_ret(out != NULL, DAV1D_ERR(EINVAL));
490:     validate_input_or_ret(in != NULL, DAV1D_ERR(EINVAL));
491: 
492:     if (!has_grain(in)) {
493:         dav1d_picture_ref(out, in);
494:         return 0;
495:     }
496: 
497:     int res = dav1d_picture_alloc_copy(c, out, in->p.w, in);
498:     if (res < 0) goto error;
499: 
500:     if (c->n_tc > 1) {
501:         dav1d_task_delayed_fg(c, out, in);
502:     } else {
503:         switch (out->p.bpc) {
504: #if CONFIG_8BPC
505:         case 8:
506:             dav1d_apply_grain_8bpc(&c->dsp[0].fg, out, in);
507:             break;
508: #endif
509: #if CONFIG_16BPC
510:         case 10:
511:         case 12:
512:             dav1d_apply_grain_16bpc(&c->dsp[(out->p.bpc >> 1) - 4].fg, out, in);
513:             break;
514: #endif
515:         default: abort();
516:         }
517:     }
518: 
519:     return 0;
520: 
521: error:
522:     dav1d_picture_unref_internal(out);
523:     return res;
524: }
