526: void dav1d_flush(Dav1dContext *const c) {
527:     dav1d_data_unref_internal(&c->in);
528:     if (c->out.p.frame_hdr)
529:         dav1d_thread_picture_unref(&c->out);
530:     if (c->cache.p.frame_hdr)
531:         dav1d_thread_picture_unref(&c->cache);
532: 
533:     c->drain = 0;
534:     c->cached_error = 0;
535: 
536:     for (int i = 0; i < 8; i++) {
537:         if (c->refs[i].p.p.frame_hdr)
538:             dav1d_thread_picture_unref(&c->refs[i].p);
539:         dav1d_ref_dec(&c->refs[i].segmap);
540:         dav1d_ref_dec(&c->refs[i].refmvs);
541:         dav1d_cdf_thread_unref(&c->cdf[i]);
542:     }
543:     c->frame_hdr = NULL;
544:     c->seq_hdr = NULL;
545:     dav1d_ref_dec(&c->seq_hdr_ref);
546: 
547:     c->mastering_display = NULL;
548:     c->content_light = NULL;
549:     c->itut_t35 = NULL;
550:     c->n_itut_t35 = 0;
551:     dav1d_ref_dec(&c->mastering_display_ref);
552:     dav1d_ref_dec(&c->content_light_ref);
553:     dav1d_ref_dec(&c->itut_t35_ref);
554: 
555:     dav1d_data_props_unref_internal(&c->cached_error_props);
556: 
557:     if (c->n_fc == 1 && c->n_tc == 1) return;
558:     atomic_store(c->flush, 1);
559: 
560:     if (c->n_tc > 1) {
561:         pthread_mutex_lock(&c->task_thread.lock);
562:         // stop running tasks in worker threads
563:         for (unsigned i = 0; i < c->n_tc; i++) {
564:             Dav1dTaskContext *const tc = &c->tc[i];
565:             while (!tc->task_thread.flushed) {
566:                 pthread_cond_wait(&tc->task_thread.td.cond, &c->task_thread.lock);
567:             }
568:         }
569:         for (unsigned i = 0; i < c->n_fc; i++) {
570:             c->fc[i].task_thread.task_head = NULL;
571:             c->fc[i].task_thread.task_tail = NULL;
572:             c->fc[i].task_thread.task_cur_prev = NULL;
573:             c->fc[i].task_thread.pending_tasks.head = NULL;
574:             c->fc[i].task_thread.pending_tasks.tail = NULL;
575:             atomic_init(&c->fc[i].task_thread.pending_tasks.merge, 0);
576:         }
577:         atomic_init(&c->task_thread.first, 0);
578:         c->task_thread.cur = c->n_fc;
579:         atomic_store(&c->task_thread.reset_task_cur, UINT_MAX);
580:         atomic_store(&c->task_thread.cond_signaled, 0);
581:         pthread_mutex_unlock(&c->task_thread.lock);
